% Define ranges for length (x) and angles
x = 1:0.1:3;
angle = linspace(7, 11, 9); % Define your desired angles (e.g., 5 angles)

% Create a grid where every length is paired with every angle
[X, Angle] = meshgrid(x, angle);

% Calculate aft diameter for all combinations
aftDia = 2 * ((3.124/2) - (X .* tand(Angle)));

% Plotting a family of curves (each line represents a different angle)
figure; %[output:86a1b56e]
plot(x, aftDia, 'LineWidth', 1.5); %[output:86a1b56e]
xlabel('Length'); %[output:86a1b56e]
ylabel('Aft Diameter'); %[output:86a1b56e]
grid on; %[output:86a1b56e]
legend(string(angle) + '°', 'Location', 'best'); %[output:86a1b56e]

% Create a table with all combinations (flattened into columns)

T = table(Angle(:), X(:), aftDia(:),'VariableNames', {'angle', 'X', 'aftDia'});
disp(T) %[output:0021fa22]

